-- 两轮都 low 的 64 道 L3 选点撤回原章节（2026-11-18）
BEGIN;
UPDATE t_question q SET chapter_id=b.chapter_id
FROM t_question_backup_20261118_l3pick b
WHERE q.id=b.id AND q.id IN (344150,346664,347504,347719,348543,349186,349189,350708,350711,350740,350742,350754,350763,350790,350952,350972,353098,358112,366178,366222,366548,366684,367602,369139,369974,370336,373055,376921,377035,378469,380610,380893,380913,385921,346694,347505,348563,348582,349204,350689,350709,350721,350750,350757,350967,351497,355139,361333,366145,366301,366549,366723,368570,369673,370335,371464,373562,373752,376108,378769,378787,380892,382687,382932);
DO $$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM t_question q JOIN t_question_backup_20261118_l3pick b ON b.id=q.id
   WHERE q.id IN (344150,346664,347504,347719,348543,349186,349189,350708,350711,350740,350742,350754,350763,350790,350952,350972,353098,358112,366178,366222,366548,366684,367602,369139,369974,370336,373055,376921,377035,378469,380610,380893,380913,385921,346694,347505,348563,348582,349204,350689,350709,350721,350750,350757,350967,351497,355139,361333,366145,366301,366549,366723,368570,369673,370335,371464,373562,373752,376108,378769,378787,380892,382687,382932) AND q.chapter_id=b.chapter_id;
  IF n <> 64 THEN RAISE EXCEPTION '撤回应为64，实际%', n; END IF;
  SELECT count(*) INTO n FROM t_question q JOIN t_chapter c ON c.id=q.chapter_id
   WHERE q.id IN (SELECT id FROM t_question_backup_20261118_l3pick) AND c.level=3;
  IF n <> 67 THEN RAISE EXCEPTION '保留L3应为67，实际%', n; END IF;
END $$;
COMMIT;
